#!/usr/bin/env bash
# BroStatus Installer fuer Linux und macOS.
# Linux:  bash brostatus-install.sh [--ziel ORDNER]
# macOS:  BroStatus-Install.command doppelklicken
PAUSE=0
ende() { if [ "$PAUSE" = "1" ]; then echo; read -r -p "  Enter zum Schließen ... " _; fi; exit "$1"; }
echo
echo "  ◆ BroStatus"
echo
if ! command -v python3 >/dev/null 2>&1; then
  if [ "$(uname)" = "Darwin" ]; then
    echo "  Python 3 fehlt. Im Terminal installieren mit:  xcode-select --install"
    echo "  (oder von https://www.python.org/downloads/) und diese Datei nochmal starten."
  else
    echo "  Python 3 fehlt. Installieren mit:  sudo apt install -y python3"
  fi
  ende 1
fi
DIR=$(mktemp -d 2>/dev/null || mktemp -d -t brostatus)
trap 'rm -rf "$DIR"' EXIT
if ! python3 - "$0" "$DIR" <<'PY'
import base64, io, sys, zipfile
data = open(sys.argv[1], "rb").read().replace(b"\r\n", b"\n")
marker = b"\n#BRO" + b"DATA#\n"
i = data.rindex(marker)
raw = base64.b64decode(b"".join(data[i + len(marker):].split()))
zipfile.ZipFile(io.BytesIO(raw)).extractall(sys.argv[2])
PY
then
  echo "  Entpacken fehlgeschlagen. Mach bitte einen Screenshot von diesem Fenster."
  ende 1
fi
if ! python3 "$DIR/brostatus/install.py" "$@"; then
  echo "  Da ist etwas schiefgelaufen. Mach bitte einen Screenshot von diesem Fenster."
  ende 1
fi
echo
echo "  ✓ Fertig! Claude Code neu starten."
ende 0
